long long stack[MAX_STACK];
int op_stack[MAX_STACK];  // 0 for none, 1 for +, 2 for *
int top = -1;

void push(long long val, int op) {
    stack[++top] = val;
    op_stack[top] = op;
}

void apply_operator(long long *result, long long val, int op) {
    if (op == 1) {
        *result += val;
    } else if (op == 2) {
