        int indent = 0;
        while (line[indent] == ' ') indent++;

        // Remove trailing newline
        line[strcspn(line, "\n")] = 0;

        // Skip empty lines
        if (line[indent] == '\0') continue;

        // Parse the token
        char *token = line + indent;
        long long val;
        int op = 0;  // 0 means it's a number

        if (token[0] == '+') {
            op = 1;
            val = atoll(token + 1);
        } else if (token[0] == '*') {
            op = 2;
            val = atoll(token + 1);
        } else {
            val = atoll(token);
        }

        // Handle indentation changes
        if (indent > prev_indent) {
            // Going deeper - push current result as pending
            push(result, 0);
            result = val;
        } else if (indent < prev_indent) {
            // Going shallower - complete current expression
            int steps = (prev_indent - indent);
            for (int i = 0; i < steps; i++) {
                long long pending_val = stack[top];
                int pending_op = op_stack[top];
                top--;

                if (pending_op == 1) {
