                } else {
                    // Should not happen for valid input
                }
            }
            // Now apply the current operator if any
            if (op != 0) {
                long long temp = result;
                result = val;
                // Need to apply the operator later when we go up
                push(temp, op);
            } else {
                result = val;
            }
        } else {
            // Same level - apply operator
            if (op != 0) {
                long long temp = result;
                result = val;
