#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXLINE 1000005
#define MAXTOK  200005

typedef struct {
    int depth;
    char type;          /* 'N' number, '+' plus, '*' mul */
    long long val;      /* for number */
} Token;

static Token tok[MAXTOK];
static int ntok;

/* Parse one line into a token:
   leading spaces = depth
   then either integer, '+' or '*'
*/
static int parse_line(const char *s, Token *t) {
    int i = 0;
    while (s[i] == ' ') i++;
    t->depth = i;

    while (s[i] && isspace((unsigned char)s[i]) && s[i] != '\n') i++;

    if (s[i] == '+' || s[i] == '*') {
        t->type = s[i];
        t->val = 0;
        return 1;
    }

    if (s[i] == '\0' || s[i] == '\n') return 0;

    t->type = 'N';
    t->val = strtoll(s + i, NULL, 10);
    return 1;
}

/* Recursive descent over preorder-with-indentation */
static long long eval_expr(int *idx) {
    Token cur = tok[*idx];
    (*idx)++;

    if (cur.type == 'N') return cur.val;

    long long a = eval_expr(idx);
    long long b = eval_expr(idx);

    if (cur.type == '+') return a + b;
    return a * b;
}

int main(void) {
    char line[MAXLINE];
    ntok = 0;

    while (fgets(line, sizeof(line), stdin)) {
        int len = (int)strlen(line);
        int all_space = 1;
        for (int i = 0; i < len; i++) {
            if (!isspace((unsigned char)line[i])) {
                all_space = 0;
                break;
            }
        }
        if (all_space) continue;

        if (ntok >= MAXTOK) return 0;
        if (parse_line(line, &tok[ntok])) ntok++;
    }

    int idx = 0;
    long long ans = eval_expr(&idx);
    printf("%lld\n", ans);
    return 0;
}

