using namespace std;

/*
  Dr. Tsukuba's parenthesis-free notation

  Since the full original statement is not shown here, we implement the standard
  interpretation of such indentation-based expressions:

  - Each line contains one token: either an integer, '+' or '*'
  - The number of leading spaces of a line is its indentation depth
  - An operator line is followed by its operands on subsequent lines with
    strictly greater indentation
  - The operands of an operator are all consecutive lines belonging to its
    subtree, i.e. until indentation becomes <= operator's indentation
  - '+' means sum of all children
  - '*' means product of all children
  - An integer is a leaf value

  We parse the input as a forest; if multiple top-level expressions exist,
  their values are output one per line.
*/

struct Line {
    int indent;
    string token;
};

vector<Line> lines;
int n;

long long parseExpr(int &i) {
    int myIndent = lines[i].indent;
    string tok = lines[i].token;

    // number
    if (tok != "+" && tok != "*") {
        long long v = stoll(tok);
        ++i;
        return v;
    }

    // operator
    char op = tok[0];
    ++i;

    vector<long long> children;
    while (i < n && lines[i].indent > myIndent) {
        children.push_back(parseExpr(i));
    }

    if (op == '+') {
        long long res = 0;
        for (auto v : children) res += v;
        return res;
    } else {
        long long res = 1;
        for (auto v : children) res *= v;
        return res;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    while (getline(cin, s)) {
        if (s.empty()) continue;
        int p = 0;
        while (p < (int)s.size() && s[p] == ' ') ++p;
        string tok = s.substr(p);
        if (!tok.empty())
            lines.push_back({p, tok});
    }

    n = (int)lines.size();
    int i = 0;
    vector<long long> ans;
    while (i < n) {
        ans.push_back(parseExpr(i));
    }

    for (int j = 0; j < (int)ans.size(); ++j) {
        if (j) cout << '\n';
        cout << ans[j];
    }
    return 0;
}

