    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<String> lines = new ArrayList<>();
        while (sc.hasNextLine()) {
            String line = sc.nextLine();
            if (line.isEmpty()) continue;
            lines.add(line);
        }

        // Stack for each depth: list of computed values
        List<List<Long>> stacks = new ArrayList<>();
        stacks.add(new ArrayList<>()); // depth 0

        for (String line : lines) {
            int depth = 0;
            while (depth < line.length() && line.charAt(depth) == ' ') depth++;
            String token = line.trim();

            // Ensure stacks has enough levels
            while (stacks.size() <= depth + 1) {
                stacks.add(new ArrayList<>());
            }

            if (token.equals("+") || token.equals("*")) {
                // Operator: combine values from one deeper level
                List<Long> deeper = stacks.get(depth + 1);
                if (deeper.isEmpty()) {
                    // No values to combine, push 0 for safety (should not happen in valid input)
                    stacks.get(depth).add(0L);
                } else {
                    long result = deeper.get(0);
                    if (token.equals("+")) {
                        for (int i = 1; i < deeper.size(); i++) {
                            result += deeper.get(i);
                        }
                    } else { // multiplication
                        for (int i = 1; i < deeper.size(); i++) {
                            result *= deeper.get(i);
                        }
                    }
                    stacks.get(depth).add(result);
                    deeper.clear();
                }
            } else {
                // It's a number
                long num = Long.parseLong(token);
                stacks.get(depth).add(num);
            }
        }

        // The final result is the single value at depth 0
        System.out.println(stacks.get(0).get(0));
    }
}

