public class Main {
    static class Token {
        int depth;
        String s;
        Token(int depth, String s) {
            this.depth = depth;
            this.s = s;
        }
    }

    static class Parser {
        List<Token> tokens;
        int n;
        int idx = 0;

        Parser(List<Token> tokens) {
            this.tokens = tokens;
            this.n = tokens.size();
        }

        long parseExpr(int depth) {
            if (idx >= n || tokens.get(idx).depth != depth) {
                throw new RuntimeException("Invalid expression");
            }

            Token t = tokens.get(idx);

            if (isNumber(t.s)) {
                idx++;
                return Long.parseLong(t.s);
            }

            String op = t.s;
            idx++;

            long left = parseExpr(depth + 1);
            long right = parseExpr(depth + 1);

            if (op.equals("+")) return left + right;
            return left * right;
        }

        boolean isNumber(String s) {
            int i = 0;
            if (s.charAt(0) == '-') {
                if (s.length() == 1) return false;
                i = 1;
            }
            for (; i < s.length(); i++) {
                if (!Character.isDigit(s.charAt(i))) return false;
            }
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<Token> tokens = new ArrayList<>();

        String line;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;

            int depth = 0;
            while (depth < line.length() && line.charAt(depth) == ' ') depth++;

            String s = line.substring(depth).trim();
            if (!s.isEmpty()) {
                tokens.add(new Token(depth, s));
            }
        }

        if (tokens.isEmpty()) return;

        Parser parser = new Parser(tokens);
        long ans = parser.parseExpr(0);
        System.out.println(ans);
    }
}

import sys

def solve():
    data = sys.stdin.read().splitlines()

    # Each entry: (indent_level, token)
    tokens = []
    for line in data:
        stripped = line.lstrip(' ')
        indent = len(line) - len(stripped)
        tokens.append((indent, stripped))

    # Stack for each depth level. We'll store numbers and operators
    # levels[0] is root level
    levels = []  # list of (numbers list, operator)

    for indent, token in tokens:
        # Ensure we have enough levels
        while len(levels) <= indent:
            levels.append([[], '+'])  # default operator is '+'

        if token in ('+', '*'):
            # set operator for this level
            levels[indent][1] = token
        else:
            # it's a number
            levels[indent][0].append(int(token))

    # Now collapse from deepest level to root
    for depth in range(len(levels)-1, 0, -1):
        nums, op = levels[depth]
        if not nums:
            val = 0
        else:
            if op == '+':
                val = sum(nums)
            else:  # '*'
                val = 1
                for n in nums:
                    val *= n
        # push result to parent level
        parent = depth - 1
        levels[parent][0].append(val)

    # Root level result
    nums_root, op_root = levels[0]
    if not nums_root:
        print(0)
    else:
        if op_root == '+':
            print(sum(nums_root))
        else:
            res = 1
            for n in nums_root:
                res *= n
            print(res)

