import sys

def main():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip() != ""]
    if not lines:
        return

    # Each line: leading spaces determine depth, then a token (+, *, or integer)
    tokens = []
    for line in lines:
        depth = 0
        while depth < len(line) and line[depth] == ' ':
            depth += 1
        token = line[depth:].strip()
        tokens.append((depth, token))

    n = len(tokens)
    idx = 0

    def parse(expected_depth):
        nonlocal idx
        depth, token = tokens[idx]
        # token at current position must have the expected depth
        # according to the notation structure
        idx += 1

        if token == '+' or token == '*':
            values = []
            while idx < n and tokens[idx][0] > expected_depth:
                values.append(parse(tokens[idx][0]))
            if token == '+':
                return sum(values)
            else:
                result = 1
                for v in values:
                    result *= v
                return result
        else:
            return int(token)

    print(parse(tokens[0][0]))

